def inject_data(slug, new_data):
    """Inject 12 new field categories into country_profile."""
    fp = os.path.join(BASE, slug, 'index.json')
    if not os.path.exists(fp):
        print(f"SKIP: {slug} - no index.json")
        return False
    
    with open(fp, 'r') as f:
        data = json.load(f)
    
    cp = data.get('country_profile', {})
    if not cp:
        print(f"SKIP: {slug} - no country_profile")
        return False
    
    # Inject each new field
    for key in ['demographics', 'natural_resources', 'military', 'trade',
                'infrastructure', 'international_memberships', 'governance_indices',
                'climate_environment', 'debt_aid', 'education', 'diaspora_migration',
                'digital_economy']:
        if key in new_data:
            cp[key] = new_data[key]
    
    data['country_profile'] = cp
    
    with open(fp, 'w') as f:
        json.dump(data, f, indent=2, ensure_ascii=False)
    
    return True

# Process each country
success = 0
fail = 0
for slug, new_data in AFRICA_DATA.items():
    if inject_data(slug, new_data):
        success += 1
        print(f"✅ {slug}")
    else:
        fail += 1
        print(f"❌ {slug}")

print(f"\nDone: {success} enriched, {fail} failed")
print(f"Remaining: {55 - success} African countries still need data")
